VALUES
  ('ch2_AHB-027', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ और बालाथल में मिली लाल जली हुई किनारों और तलों वाली छोटी ‘यू’ आकार की अग्नि-रचनाओं को अध्ययन में किस उपयोग से जोड़ा गया?', 'ताँबे को गलाने और गर्म करने वाली भट्टियों के रूप में; यह उत्खनन-साक्ष्य की लेखकीय व्याख्या है।', 'hi', 'https://ignca.gov.in/Asi_data/87125.pdf', 'AHB-027 — S30 — Shinde, Possehl और Sinha-Deshpande, The Ceramic Assemblage in Protohistoric Mewar, Puratattva 32 (2001–02), मुद्रित पृ. 7; PDF page-image review लंबित।', 'NEEDS_REVIEW', 0.80, '86a0e3ffee72089bbdc57322fc808e7c68ee046df6b00ac7701824b259cb17f6', NULL),
  ('ch2_AHB-028', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'बालाथल में एक के ऊपर एक किस प्रकार की दो भट्टियाँ मिलीं?', 'दो आयताकार मृद्भांड पकाने की भट्टियाँ।', 'hi', 'https://ignca.gov.in/Asi_data/87125.pdf', 'AHB-028 — S30 — The Ceramic Assemblage in Protohistoric Mewar, Puratattva 32 (2001–02), मुद्रित पृ. 7; PDF page-image review लंबित।', 'NEEDS_REVIEW', 0.80, '6292ac5ae5c92b8f102cc481b27588978d863758d72eb9dacdc79b7a0ba84c5f', NULL),
  ('ch2_AHB-029', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ स्थल के ताम्रपाषाणिक काल के मृद्भांडों के तीन उपचरण कौन-से हैं और उनकी अनुमानित तिथियाँ क्या दी गई हैं?', 'प्रथम उपचरण 2580–2170 ईसा पूर्व, द्वितीय 2170–2080 ईसा पूर्व और तृतीय 2080–1500 ईसा पूर्व। ये आहड़ स्थल के लिए उसी अध्ययन में उद्धृत तिथियाँ हैं, पूरे आहड़-बनास क्षेत्र की निर्विवाद काल-सीमा नहीं।', 'hi', 'https://ignca.gov.in/Asi_data/87125.pdf', 'AHB-029 — S30 — The Ceramic Assemblage in Protohistoric Mewar, Puratattva 32 (2001–02), मुद्रित पृ. 7; कालक्रम स्रोत-विशिष्ट है और स्वतंत्र समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0f2e972a5e5fbdadee258fadbfbd18620eb65441af82b5d0f9a2a29d2c9c0b0b', NULL),
  ('ch2_AHB-030', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ स्थल के ताम्रपाषाणिक तृतीय उपचरण की दो प्रमुख मृद्भांड विशेषताएँ क्या थीं?', 'तीव्र कोण वाले काले-लाल मृद्भांड के कटोरे और गुजरात के रंगपुर से मिलते-जुलते चमकीले लाल मृद्भांड।', 'hi', 'https://ignca.gov.in/Asi_data/87125.pdf', 'AHB-030 — S30 — The Ceramic Assemblage in Protohistoric Mewar, Puratattva 32 (2001–02), मुद्रित पृ. 7; तुलना को रंगपुर-समरूपता तक सीमित रखें।', 'NEEDS_REVIEW', 0.80, 'c1226a04779c7cf687fe91cdf13f68777e8dc0774dbb7432c4ce2e445f0b24b6', NULL),
  ('ch2_AHB-031', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति के मध्य चरण में बस्तियों की संरचना और मृद्भांडों में कौन-से परिवर्तन दिखते हैं?', 'किलेबंदी और भंडारण संरचनाएँ उभरीं; चाक पर बने तथा उच्च गुणवत्ता वाले मृद्भांड प्रचलित हुए; निर्माण में मुख्यतः कच्ची ईंट और पत्थर का उपयोग हुआ।', 'hi', 'https://ignca.gov.in/Asi_data/88233.pdf', 'AHB-031 — S31 — Debasri Dasgupta, Site Catchment Analysis of the Chalcolithic Settlement of Gilund in the Banas Basin, Puratattva 35 (2004–05), मुद्रित पृ. 103; लेख में उद्धृत Shinde et al. (2001–02) का सांस्कृतिक चरण-विभाजन।', 'NEEDS_REVIEW', 0.80, 'd0e753c8c6ecf118b823c59d84c5e0cb2d4ebfe6b4ae76a89e02a69db47cd328', NULL),
  ('ch2_AHB-032', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति के अंतिम चरण में बस्ती-निर्माण और मृद्भांडों का स्वरूप किस प्रकार बदलता बताया गया है?', 'फिर से लकड़ी-मिट्टी की बुनावट वाली संरचनाएँ और मोटे, कम पके मृद्भांड दिखाई देते हैं; संबंधित अध्ययन इसे अवनति का संकेत मानता है।', 'hi', 'https://ignca.gov.in/Asi_data/88233.pdf', 'AHB-032 — S31 — Debasri Dasgupta, Puratattva 35 (2004–05), मुद्रित पृ. 103; अवनति मूल लेखकों की व्याख्या है, निर्विवाद निष्कर्ष नहीं।', 'NEEDS_REVIEW', 0.80, 'a10663f290100107e45ba9b29e2725e800cf4bd761e284d939701d81be7dd8b2', NULL)
